<?php

namespace App\Services;

use App\Models\TutorialProgress;
use App\Models\User;

class TutorialCatalog
{
    public function for(User $user): array
    {
        if (! $user->isActive()) {
            return ['guides' => [], 'progress' => []];
        }
        $guides = $this->guides($user->role);

        return ['guides' => $guides, 'progress' => TutorialProgress::where('user_id', $user->id)
            ->whereIn('guide_key', array_column($guides, 'id'))->get(['guide_key', 'version', 'step_key', 'viewed_at'])->toArray()];
    }

    public function guides(string $role): array
    {
        $initialPassword = (bool) config('student-setup.initial_password_enabled');
        $accessInstructions = $initialPassword
            ? 'Tell the learner to sign in with their student ID as both username and temporary password, then save a different private password before opening the course. No email or setup code is required.'
            : (config('student-setup.password_enabled')
                ? 'Give the learner their own private setup code. They use their student ID and that code to choose a password; no email is required.'
                : 'Use the enabled account activation method. Where matching verified Google access is available, the learner may use it. Otherwise, privately provide the existing email activation code so they can set a password.');
        $s = fn ($id, $page, $target, $title, $text, $missing) => compact('id', 'page', 'target', 'title', 'text', 'missing');
        $g = fn ($id, $title, $purpose, $prerequisite, $result, $steps) => compact('id', 'title', 'purpose', 'prerequisite', 'result', 'steps') + [
            'version' => $id === 'admin-students' ? 2 : 1, 'role' => $role, 'support' => $role === 'student' ? 'Ask your assigned teacher or administrator for a password reset, your teacher about activities, and your administrator about enrollment.' : 'Contact your administrator for account or section access. Refer content questions to the authorized faculty reviewer.',
        ];
        $classes = $s('sections', 'classes', '#classesContent', 'Find your class section', 'Open your section and check its name, semester, and assigned activities. On staff pages, expand the section row to see details.', 'No sections yet? Ask the administrator to check your enrollment or assignment.');
        $progress = $s('progress', 'reports', '#workspaceTool', 'Read recorded progress', 'Choose a section, activity, or date range. Reports show saved work; tutorial viewing does not count as lesson completion.', 'Reports require a connection. If there are no records, check the filters and whether work has synchronized.');
        $preview = $s('preview', 'manager', '[data-open-package]', 'Preview the content', 'Expand a content row, then use Preview draft or Open lesson to inspect anatomy, directions, and safety information. Return to this page when ready.', 'Expand a content row. If there is no content to review, wait for an instructor submission.');
        $review = $s('decision', 'manager', '[data-species-review]', 'Record an independent review', 'Check the evidence, choose approval or requested changes, and write meaningful notes. Approval requires curriculum and safety confirmation. Submit only when your review is complete.', 'Expand a version in review. A current approval or your own upload will not offer an independent review form.');
        $safetyReview = $s('safety-review', 'safety', '[data-module-review]', 'Review Safety & Tools', 'Preview the module, check handling and safety directions, then record a decision with the procedure evidence reference. An administrator publishes after approval.', 'Expand a module in review. The uploader cannot approve it; already approved or unavailable versions do not offer a review form.');

        return match ($role) {
            'student' => [
                $g('student-orientation', 'First session: account and orientation', 'Know where to go and what to do before lessons open.', 'An activated student account. No anatomy lesson or safety-module assignment is required for this guide.', 'Your orientation guide is marked viewed. This does not complete a lesson, a safety prerequisite, or research consent.', [
                    $s('welcome', 'home', '#studentOrientationPath', 'Start with your own account', 'You are signed in. Use only the account supplied by the administrator. Keep your private password to yourself; do not create a second account if a section is missing. '.$accessInstructions, 'Return to Home for your first-session checklist.'),
                    $s('purpose', 'about', '#tutorialGuides', 'Understand the purpose', 'AquaDissect supports preparation for faculty-supervised physical laboratory work. Illustrations are teaching aids. This first session covers account access and navigation, not an anatomy assessment or research data collection.', 'This guide is available even while content is under review.'),
                    $s('section', 'classes', '#classesContent', 'Check your class section', 'Open Class sections and check the section, semester and instructor. If the section is missing or incorrect, tell the administrator or instructor. You can finish this orientation while enrollment is being checked.', 'An empty section list means enrollment needs checking; it is not a reason to create another account.'),
                    $s('availability', 'library', '#speciesLibraryContent', 'Recognize content availability', 'Rabbitfish is the current study focus. An empty lesson list means no approved lesson is assigned to you. Safety and anatomy content must be independently reviewed, published and assigned before use; orientation does not unlock them.', 'You do not need an available lesson to finish this orientation.'),
                    $s('finish', 'about', '#tutorialGuides', 'Finish orientation and know your next step', 'Choose Finish guide to save orientation viewing to your account. Return to Home to check the saved status. For this first session, stop after activation and orientation. Follow your instructor’s directions for later approved activities. Account activation is not research consent.', 'Reconnect if saving fails, then use Retry saving. Do not claim completion before the saved confirmation appears.'),
                ]),
                $g('student-class', 'Find your class', 'Know which section and activities belong to you.', 'An activated account and administrator enrollment.', 'You know your assigned class and who to contact if it is missing.', [$classes, $s('activities', 'classes', '.class-card', 'Check your activities', 'Look for assigned species and the Safety & Tools prerequisite. Use the activity button for your section.', 'If your class is missing, ask the administrator to verify enrollment.')]),
                $g('student-safety', 'Complete Safety & Tools', 'Prepare before opening anatomy lessons.', 'A reviewed, published module assigned to your section.', 'You know how to finish every required step and submit the tool activity.', [
                    $s('open', 'safety', '[data-open-learning-module]', 'Start or resume the module', 'Select Start module or Resume module. If nothing is assigned, ask your teacher what to do next.', 'Your teacher or administrator must assign a published Safety & Tools module.'),
                    $s('steps', 'safety', '#safetyModuleExperience', 'Read every required step', 'Open the module yourself. Read the captions, inspect the tools, and finish each required step using the module controls.', 'Select Start module first. This tutorial does not open or complete it for you.'),
                    $s('activity', 'safety', '#safetyModuleExperience', 'Submit the tool-selection activity', 'Answer and submit once after viewing all required steps. You may retry without limit. The score is retained but does not decide completion.', 'Open your assigned module and follow its steps to the activity.'),
                ]),
                $g('student-lesson', 'Open an assigned lesson', 'Choose the correct lesson for your class.', 'An assigned published lesson and its satisfied prerequisite.', 'You can recognize a locked lesson and open one when eligible.', [$classes, $s('unlock', 'library', '#speciesLibraryContent', 'Check lesson access', 'If a lesson is locked, complete Safety & Tools. Only authorized staff can grant a documented exception.', 'Ask your teacher if no lesson is assigned.'), $s('open', 'library', '[data-open-package]', 'Open your lesson', 'Select Open lesson. If asked, choose the class section for this attempt.', 'No open button? Complete the prerequisite or ask your teacher about the assignment.')]),
                $g('student-explore', 'Explore anatomy and activities', 'Learn how to move through a lesson.', 'An available assigned lesson.', 'You know where to explore structures, follow directions, and submit your own work.', [
                    $s('open', 'library', '[data-open-package]', 'Enter the lesson', 'Open an available lesson yourself. The tutorial will stay available while you explore.', 'Complete Safety & Tools and check your assignment first.'),
                    $s('explore', 'library', '#lesson-content', 'Explore and follow the sequence', 'Use the anatomy labels and hotspots to read about structures. Follow the guided procedure and the activity instructions shown in the lesson.', 'Open a lesson first to see its learning controls.'),
                    $s('save', 'library', '#lesson-content', 'Finish the formative activity', 'Review your answers, submit when ready, and read the feedback. Confirm that your work was saved or queued before leaving.', 'Open the lesson and follow its activity instructions. Viewing this guide does not submit answers.'), $progress,
                ]),
                $g('student-results', 'Find your saved progress', 'Check what has been recorded.', 'A signed-in account; recorded work appears after saving or synchronization.', 'You can distinguish recorded results from work awaiting synchronization.', [$progress, $s('safety', 'safety', '#safetyToolsContent', 'Check safety completion', 'Your module card shows progress and completion. Reconnect with the same account if offline work has not synchronized.', 'If your module is missing, ask your teacher about the assignment.')]),
            ],
            'instructor' => [
                $g('teacher-sections', 'Find your assigned sections', 'Start with the classes you teach.', 'Administrator approval and section assignment.', 'You can locate student and activity information.', [$classes, $s('roster', 'classes', '.roster-details', 'Inspect your class', 'Expand the section row and open View students, safety status, and progress.', 'Expand a section row first. Ask the administrator if your section is missing.')]),
                $g('teacher-assign', 'Assign a published activity', 'Give your class an available lesson.', 'An active assigned section and published content.', 'You know how to select a lesson and review an assignment before saving.', [$s('activities', 'assignments', '[data-assignment-form]', 'Choose your section and lesson', 'Expand the section row, then choose the published package for the correct section. Check its version and any due date before saving.', 'Ask the administrator to assign an active section. Content must be published first.'), $classes]),
                $g('teacher-progress', 'Monitor learner progress', 'Find learners who may need support.', 'An assigned section.', 'You can inspect safety status and recorded lesson attempts.', [$classes, $progress]),
                $g('teacher-exceptions', 'Document a prerequisite exception', 'Use a justified exception when faculty direction requires it.', 'An assigned section with a safety prerequisite.', 'You know how to grant or revoke a documented exception.', [$classes, $s('exception', 'classes', '[data-section-override]', 'Review and document the reason', 'Expand your section. Use the section exception form for the whole class, or a learner exception control for one learner. Enter a clear reason before submitting. Use Revoke when an exception is no longer needed.', 'Expand a section with an assigned safety module. Exceptions do not mark safety learning as completed.')]),
                $g('teacher-content', 'Submit and independently review content', 'Move prepared content through the review process.', 'Prepared content or a version awaiting review.', 'You understand submission, independent review, and administrator publication.', [$s('submit', 'manager', '[data-submit-package]', 'Send a prepared draft for review', 'Expand your own draft, preview and check it, then send it for faculty review when ready.', 'You need your own prepared draft. Published versions cannot be edited.'), $preview, $review, $safetyReview]),
            ],
            'program_head' => [
                $g('head-overview', 'Review section progress', 'See activity across MB 304L sections.', 'An active Program Head account.', 'You can inspect sections without changing teaching assignments.', [$classes, $progress]),
                $g('head-reports', 'Filter and read learning reports', 'Use recorded results to inform follow-up.', 'Recorded section activity.', 'You can filter results and export the displayed operational records.', [$progress, $s('export', 'reports', '#workspaceTool a[href*="format=csv"]', 'Export the filtered report', 'Apply the intended filters before exporting CSV. Keep identifiable learner records within authorized use. These records alone do not establish learning effectiveness.', 'Wait for reports to load and apply your filters. Reconnect if the report is unavailable.')]),
                $g('head-preview', 'Inspect content awaiting review', 'Examine the learning experience before deciding.', 'A submitted version in faculty review.', 'You can locate and preview content that needs a decision.', [$preview, $s('tools', 'safety', '[data-open-learning-module]', 'Inspect the laboratory module', 'Expand a module row and preview its tools, captions, handling directions, and activity.', 'A module must be available. Expand its row to find Preview module.')]),
                $g('head-review', 'Record approval or requested changes', 'Document an independent content review.', 'A version in review that you did not upload.', 'Your decision is recorded; publication remains an administrator action.', [$review, $safetyReview]),
            ],
            'admin' => [
                $g('admin-approve', 'Approve instructor requests', 'Give verified teachers access.', 'A genuine pending instructor request.', 'You know where to approve a verified request and assign its sections.', [$s('approve', 'home', '[data-approve-account]', 'Review the pending request', 'Verify the instructor through your institutional process before selecting Approve. Approval alone does not assign a section.', 'The approval queue is clear when no requests are pending.'), $s('assign', 'roster', '[data-instructor-form]', 'Assign the teacher to a section', 'In People & sections, expand the intended section and choose the approved instructor.', 'Create a section and approve an instructor first. Expand the section row to see its controls.')]),
                $g('admin-sections', 'Prepare sections and assign teachers', 'Set up the semester before enrolling learners.', 'Verified academic year, semester, section, and approved instructors.', 'You can create the correct offering and assign its instructor.', [$s('create', 'roster', '#offeringCreateForm', 'Add a section', 'Open Add a section. Enter the academic year, semester, and section code. Check them before submitting.', 'Open the Add a section disclosure in People & sections.'), $s('assign', 'roster', '[data-instructor-form]', 'Assign an instructor', 'Expand the section row, choose the approved instructor, and save the assignment.', 'A section and active instructor are required. Expand the section row.')]),
                $g('admin-students', 'Provision and enroll students', 'Prepare accounts from a verified class roster.', 'A verified roster and an existing section.', 'You know how to create or enroll a learner and explain account access.', [$s('student', 'roster', '#studentCreateForm', 'Add or enroll a student', 'Open Add one student, choose the section, and enter the verified institutional details. Submit only after checking them.', 'Create a section first, then open Add one student.'), $s('activation', 'roster', '#rosterContent', 'Explain first-time access', $accessInstructions.' Research consent remains separate.', 'Check the account and section before giving access instructions.'), $s('password-support', 'roster', '#rosterContent', 'Reset a student password and review history', $initialPassword ? 'After verifying the student’s identity through your support process, choose Reset password, select the reason and review the confirmation. Administrators and the assigned active-section teacher can reset the student. The student must replace the student-ID temporary password again. Password history records who, when and why; previous online sessions lose access.' : 'Follow the enabled account support method. Student-ID password resets are available only when that account policy is enabled.', 'Expand a student row. Assigned teachers use their own Class sections. Program Heads cannot reset passwords.')]),
                $g('admin-head', 'Assign Program Head access', 'Give a designated staff member oversight and review responsibilities.', 'An active Instructor account selected through your institutional process.', 'You can change the role explicitly and see its retained history.', [$s('choose', 'access', '#staffRoleTools', 'Choose the designated staff account', 'Select an active instructor and choose Program Head. Existing section assignments remain recorded, but instructor management privileges stop while this role is active.', 'Only administrators can assign roles. An active instructor account is required.'), $s('confirm', 'access', '#staffRoleTools', 'Confirm the role change', 'Review the confirmation before applying the change. You can later restore Instructor access. The account refreshes when it next checks its session.', 'Open Account roles while signed in as an administrator.')]),
                $g('admin-publish', 'Publish independently approved content', 'Make reviewed content available for teaching.', 'A current independent faculty approval for the exact version.', 'You understand approval, publication, and subsequent class assignment.', [$s('species', 'manager', '[data-publish-package]', 'Publish an approved species version', 'Expand the reviewed version, check its approval record, then choose Publish approved version. Publishing does not automatically enroll learners.', 'Publication is offered only after current independent approval. Ask a reviewer to resolve pending changes.'), $s('safety', 'safety', '[data-publish-learning-module]', 'Publish the approved safety module', 'Expand the approved module and publish when ready. Started learners retain their pinned version; unstarted assignments can move to the new version.', 'A current independent faculty approval is required before publication.')]),
            ],
            default => [],
        };
    }
}
